-- introSentences: when each sentence of the narration starts, for the subtitles.
ST.introSentences = {
    [1] = {
        { t = 0.42, text = [=[The Cosmic Index of Summonable Persons is, by general agreement, the most important document in Azeroth that nobody has ever read.]=] },
        { t = 10.41, text = [=[It lists every being that may legally be summoned, in alphabetical order, and it was compiled by a single clerk who had, at the time, been on shift for nine thousand years.]=] },
    },
    [2] = {
        { t = 0.41, text = [=[Somewhere around the letter Z, the clerk sneezed.]=] },
        { t = 4.80, text = [=[This is generally accepted to be the origin of the entire problem.]=] },
    },
    [3] = {
        { t = 0.41, text = [=[As a result of the sneeze, a Licensed Summoning Liaison, Third Class, named Zennit was entered into the Index as the default recipient of every Ritual of Summoning completed within range of his name.]=] },
        { t = 14.60, text = [=[This includes rituals meant for other people.]=] },
        { t = 18.65, text = [=[It includes rituals meant for nobody.]=] },
        { t = 22.38, text = [=[It includes at least one ritual intended for a goat.]=] },
    },
    [4] = {
        { t = 0.41, text = [=[Zennit did what any reasonable person would do.]=] },
        { t = 4.76, text = [=[He looked for the form.]=] },
        { t = 7.47, text = [=[The form turned out to be Form 27B slash 6, which is referenced throughout the Index and has never been seen.]=] },
        { t = 16.18, text = [=[Several scholars believe it does not exist.]=] },
        { t = 20.34, text = [=[Zennit believes that is exactly what a form would say.]=] },
    },
    [5] = {
        { t = 0.41, text = [=[Meanwhile, the Ritual of Summoning, a spell with a great deal of free time and a fragile sense of self, had formed an attachment.]=] },
        { t = 9.63, text = [=[It does not want gold.]=] },
        { t = 12.53, text = [=[It wants, in its own words, attention and closure.]=] },
        { t = 17.38, text = [=[It will, however, accept fifty silver as a gesture.]=] },
    },
    [6] = {
        { t = 0.42, text = [=[And so every completed summon is recorded as an installment on a debt Zennit never agreed to, cannot find the paperwork for, and is nevertheless making definite progress on.]=] },
    },
    [7] = {
        { t = 0.42, text = [=[You, meanwhile, are a party of friends who have noticed that Zennit is, technically, very easy to summon.]=] },
        { t = 7.43, text = [=[The Index has no objection.]=] },
        { t = 10.94, text = [=[The Index has never been asked.]=] },
    },
    [8] = {
        { t = 0.41, text = [=[This is the story of his week, and the week after that.]=] },
        { t = 4.62, text = [=[If the form is ever found, you will be the first to know.]=] },
        { t = 9.03, text = [=[Or the last.]=] },
        { t = 11.44, text = [=[The Index is unclear.]=] },
    },
    [9] = {
        { t = 0.40, text = [=[The rules, such as they are.]=] },
        { t = 3.53, text = [=[Each week, the group earns points by summoning Zennit, with more points for places that are remote, or dangerous, or frankly unreasonable.]=] },
        { t = 13.25, text = [=[Zennit, for his part, holds a secret list, which he may complete at any time, and which he will not discuss.]=] },
        { t = 20.34, text = [=[If the group has more points at the end of the week, the Index records a victory for persistence.]=] },
    },
    [10] = {
        { t = 0.40, text = [=[If Zennit completes his list first, he wins the week, and cannot be summoned for the seven days that follow.]=] },
        { t = 7.42, text = [=[He may refuse a summons.]=] },
        { t = 10.42, text = [=[He may demand fifty silver, in cash, with no receipt.]=] },
        { t = 15.32, text = [=[Or he may suggest dice.]=] },
        { t = 18.59, text = [=[The Index will accept any of these.]=] },
        { t = 22.52, text = [=[The Index accepts most things.]=] },
    },
    [11] = {
        { t = 0.41, text = [=[At the end of the week, the Index counted.]=] },
        { t = 4.16, text = [=[It counted the summons, and the places, and the refusals, and the dice, and then it counted them again, because the total was not the one it had expected.]=] },
        { t = 14.05, text = [=[Zennit had won.]=] },
        { t = 16.68, text = [=[He had won the dice when it mattered, and he had been summoned, entirely by accident, to several of the places on his list.]=] },
    },
    [12] = {
        { t = 0.41, text = [=[The Index informed Zennit by registered letter, which he did not trust, and which he read twice.]=] },
        { t = 7.14, text = [=[For seven days, no ritual could find him.]=] },
        { t = 11.14, text = [=[The party gathered in a circle and said his name, and the Index replied that the Licensed Summoning Liaison was, regrettably, on leave.]=] },
        { t = 20.78, text = [=[Zennit spent the week doing nothing at all, which he had always suspected to be the correct amount.]=] },
    },
    [13] = {
        { t = 0.41, text = [=[The following week, the group won.]=] },
        { t = 3.79, text = [=[Nobody was more surprised than the group.]=] },
        { t = 7.79, text = [=[The Index counted the summons, and the places, and the refusals, and found that the party had finished ahead of Zennit, despite his head start, and despite a run of dice that had, until then, been entirely reliable.]=] },
        { t = 21.87, text = [=[The Index checked the sum three times.]=] },
        { t = 25.84, text = [=[It was not wrong.]=] },
    },
    [14] = {
        { t = 0.40, text = [=[A victory for persistence, as the rules had promised.]=] },
        { t = 5.04, text = [=[The party celebrated in the traditional manner, by summoning Zennit to the celebration.]=] },
        { t = 11.13, text = [=[He arrived, as he always did, slightly confused, and was handed a small cake, which he did not trust.]=] },
        { t = 18.53, text = [=[The Index recorded the week as a narrow win for hope over paperwork, and began, quietly, to count the next one.]=] },
    },
    [15] = {
        { t = 0.41, text = [=[Zennit's second week off began, as these things do, with a parcel.]=] },
        { t = 5.58, text = [=[Inside was a brass key, a luggage tag that said Side Door, and a note that said, helpfully, nothing.]=] },
        { t = 13.07, text = [=[He checked the key against his secret list.]=] },
        { t = 17.06, text = [=[It was the first item.]=] },
        { t = 20.08, text = [=[It had been the first item all along, and he had been too busy being summoned to read it.]=] },
    },
    [16] = {
        { t = 0.41, text = [=[The side door of the Index was exactly where the key said it would be, behind the letter Q, between a filing cabinet and a sign that said Please Do Not.]=] },
        { t = 10.73, text = [=[Zennit went in.]=] },
        { t = 13.13, text = [=[Beyond it was a quiet corridor, a very old kettle, and a desk with a chair that fit him suspiciously well.]=] },
        { t = 21.00, text = [=[He did not sit down.]=] },
        { t = 23.72, text = [=[He ticked the first item on his list, and somewhere in the Index, a clerk cleared his throat.]=] },
    },
    [17] = {
        { t = 0.42, text = [=[The group's second win arrived with an unexpected receipt.]=] },
        { t = 5.51, text = [=[Tucked into the cake box, under the napkins, was a sheet of faint blue carbon paper, which, held up to the light, showed the cover of a form.]=] },
        { t = 15.03, text = [=[The title was smudged.]=] },
        { t = 17.91, text = [=[The number was not.]=] },
        { t = 20.66, text = [=[It was Form 27B slash 6, or at least the part that had pressed through to the next page.]=] },
    },
    [18] = {
        { t = 0.40, text = [=[Scholars had always maintained that the form did not exist.]=] },
        { t = 5.35, text = [=[The carbon copy suggested otherwise.]=] },
        { t = 9.46, text = [=[It suggested that the form had once been filled in, by someone, in triplicate, and that the other two copies had gone to the Index and to the Ritual of Summoning.]=] },
        { t = 20.06, text = [=[The party kept the third.]=] },
        { t = 23.07, text = [=[The Index asked for it back.]=] },
        { t = 26.39, text = [=[The party said they would think about it.]=] },
    },
    [19] = {
        { t = 0.41, text = [=[Zennit's third week off began with the second item on his list, which was not an errand.]=] },
        { t = 6.71, text = [=[It was a pamphlet, titled Module One: Alphabetical Order.]=] },
        { t = 11.99, text = [=[The third item was Module Two: The Care and Feeding of Ink.]=] },
        { t = 17.29, text = [=[He understood, slowly, that the list had never been a list of errands.]=] },
        { t = 22.51, text = [=[It was a syllabus.]=] },
    },
    [20] = {
        { t = 0.42, text = [=[He studied in the corridor behind the side door, with the kettle for company.]=] },
        { t = 5.90, text = [=[By Friday he could recite the alphabet forwards, which the Index considered a promising start, and backwards, which it considered a gift.]=] },
        { t = 15.13, text = [=[On the desk, a nameplate was being engraved.]=] },
        { t = 19.50, text = [=[It had not yet been decided whose.]=] },
    },
    [21] = {
        { t = 0.41, text = [=[The group's third win was celebrated without cake, because the Ritual of Summoning had begun to answer back.]=] },
        { t = 8.01, text = [=[It did this in the only way a spell can, by glowing in a meaningful manner whenever the carbon copy was in the room.]=] },
        { t = 16.09, text = [=[The party found this unsettling.]=] },
        { t = 19.72, text = [=[They also found it encouraging.]=] },
        { t = 23.02, text = [=[It is possible to feel both.]=] },
    },
    [22] = {
        { t = 0.42, text = [=[The glow led them to a cellar beneath a tavern, where a chalk circle had been drawn on the floor so long ago that the tavern had been built on top of it.]=] },
        { t = 9.87, text = [=[In a crack at its centre, wedged tight, was a folded sheet of paper.]=] },
        { t = 15.19, text = [=[It was Form 27B slash 6.]=] },
        { t = 19.46, text = [=[The Ritual had been sitting on it for as long as anyone could remember, with the quiet pride of a spell that has finally been asked the right question.]=] },
    },
    [23] = {
        { t = 0.40, text = [=[In the fourth week, the clerk found Zennit in the corridor, reciting.]=] },
        { t = 5.37, text = [=[The clerk was very old and very tired, and had not left his desk since the invention of desks.]=] },
        { t = 12.41, text = [=[He looked at Zennit for a long time.]=] },
        { t = 16.00, text = [=["You are in the wrong book," he said.]=] },
        { t = 19.30, text = [=[Zennit replied that he had been told.]=] },
        { t = 23.08, text = [=[The clerk said that this was not a criticism.]=] },
    },
    [24] = {
        { t = 0.41, text = [=[The clerk showed him the desk.]=] },
        { t = 3.57, text = [=[It was enormous, and covered in nine thousand years of unfinished business, most of which turned out, on inspection, to be about Zennit.]=] },
        { t = 12.77, text = [=["I am not asking you to take it," said the clerk.]=] },
        { t = 16.46, text = [=["I am only asking you to hold the pen, while I find my hat."]=] },
    },
    [25] = {
        { t = 0.41, text = [=[The Ritual of Summoning, once asked, was only too happy to talk.]=] },
        { t = 5.51, text = [=[It had never wanted gold, it explained.]=] },
        { t = 9.52, text = [=[It had wanted a proper ending: a last summons, performed with attention, followed by closure.]=] },
        { t = 16.08, text = [=[It had been waiting for one since before the tavern.]=] },
        { t = 20.28, text = [=[It was very good about it.]=] },
    },
    [26] = {
        { t = 0.40, text = [=[The price was modest.]=] },
        { t = 3.30, text = [=[Fifty silver, paid in person, in cash.]=] },
        { t = 7.60, text = [=[And the third copy of the form, to complete the set.]=] },
        { t = 11.79, text = [=[The Ritual had waited a very long time for the set.]=] },
        { t = 16.28, text = [=[It understood how that looked, and said so, which the party agreed was decent of it.]=] },
    },
    [27] = {
        { t = 0.40, text = [=[In the fifth week, the clerk found his hat.]=] },
        { t = 4.14, text = [=[It was on his head.]=] },
        { t = 6.63, text = [=[He said this was the sort of thing that happens to a person who has looked at nothing but the Index for nine thousand years.]=] },
        { t = 15.35, text = [=[He shook Zennit's hand, left through the side door, and was last seen walking toward the sea, without his coat, visibly lighter.]=] },
    },
    [28] = {
        { t = 0.40, text = [=[Zennit sat down.]=] },
        { t = 3.11, text = [=[The chair fit, as expected.]=] },
        { t = 6.51, text = [=[He read the Index from the beginning, which took a week, and found it sound, apart from the letter Z, where one entry had been smudged and then misfiled by a sneeze.]=] },
        { t = 17.09, text = [=[He corrected it with a single stroke of the pen.]=] },
        { t = 20.96, text = [=[Somewhere far below, the Ritual of Summoning went quiet.]=] },
    },
    [29] = {
        { t = 0.41, text = [=[Then he did what no clerk had done in nine thousand years.]=] },
        { t = 5.42, text = [=[He added entries.]=] },
        { t = 8.20, text = [=[The party went in first, in alphabetical order, each with a short note of thanks.]=] },
        { t = 14.17, text = [=[Zennit, Licensed Summoning Liaison, Third Class, was promoted to Clerk, and invited the party to summon him whenever they liked.]=] },
        { t = 23.10, text = [=[He would, of course, always accept.]=] },
        { t = 26.67, text = [=[The Index wrote that down.]=] },
    },
    [30] = {
        { t = 0.42, text = [=[On the group's fifth win, the party went down into the cellar with fifty silver in cash, the third copy of the form, and the kind of nerves usually reserved for exams.]=] },
        { t = 11.76, text = [=[The Ritual of Summoning glowed.]=] },
        { t = 15.24, text = [=[It was clear that it, too, had prepared something.]=] },
    },
    [31] = {
        { t = 0.40, text = [=[The silver was counted.]=] },
        { t = 3.49, text = [=[The copy was handed over.]=] },
        { t = 6.84, text = [=[The Ritual, for the first time in its existence, was given a receipt: Form 27B slash 6, complete in triplicate, and stamped.]=] },
        { t = 16.32, text = [=[The Index approved, from a distance.]=] },
        { t = 19.86, text = [=[Closure, it turned out, was mostly paperwork.]=] },
    },
    [32] = {
        { t = 0.40, text = [=[The Ritual let go.]=] },
        { t = 3.16, text = [=[Zennit felt it as a small click, like a lock turning in a door he had never noticed.]=] },
        { t = 9.13, text = [=[For the first time in his life, he was summoned by nobody.]=] },
        { t = 13.36, text = [=[He stood in the cellar, free.]=] },
        { t = 16.53, text = [=[Then he did the only thing he could think of, and summoned the party to his place, for cake.]=] },
        { t = 22.37, text = [=[They accepted.]=] },
        { t = 24.73, text = [=[It was, by general agreement, a very small cake.]=] },
    },
}
